// Fonte Inter (OFL) embutida como Buffer/base64 para o resvg desenhar
// texto de forma independente do SO — o ambiente serverless da Vercel
// (Linux) não vem com NENHUMA fonte instalada, então o sharp/librsvg
// desenhava caixas no lugar de texto. resvg recebe a fonte via buffer
// (fontBuffers), sem depender de fontconfig/fontes do sistema.
export const FONT_FAMILY = "Inter";

export const FONT_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 500, data: "" },
  { weight: 600, data: "" },
  { weight: 800, data: "" },
  { weight: 900, data: "" },
  { weight: 400, data: "" },
];
